397	+      getAbstractFileByPath: (path: string) => filesByPath.get(path) ?? null,
398	+      getFileByPath: (path: string) => filesByPath.get(path) ?? null,
399	+      getMarkdownFiles,
400	+    },
401	+  } as unknown as App;
402	+
403	+  return { app, getMarkdownFiles };
