1	import { TFile, App } from "obsidian";
2	import type DiscourseGraphPlugin from "~/index";
3	import { BulkImportPattern, BulkImportCandidate, DiscourseNode } from "~/types";
4	import { getDiscourseNodeFormatExpression } from "~/utils/getDiscourseNodeFormatExpression";
5	import { extractContentFromTitle } from "~/utils/extractContentFromTitle";
6	
7	// This is a workaround to get the datacore API.
8	// TODO: Remove once we can use datacore npm package
9	export type AppWithPlugins = App & {
10	  plugins: {
11	    plugins: {
12	      [key: string]: {
13	        api: unknown;
14	      };
15	    };
16	  };
17	};
18	
19	type DatacorePage = {
20	  $name: string;
21	  $path?: string;
22	};
23	
24	type DatacoreApi = {
25	  core?: {
26	    initialized?: boolean;
27	  };
28	  query: (query: string) => DatacorePage[];
29	};
30	
31	export class QueryEngine {
32	  private app: App;
33	  private dc: DatacoreApi | undefined;
34	  private readonly MIN_QUERY_LENGTH = 2;
35	
36	  constructor(app: App) {
37	    const appWithPlugins = app as AppWithPlugins;
38	    this.dc = appWithPlugins.plugins?.plugins?.["datacore"]?.api as
39	      | DatacoreApi
40	      | undefined;
41	    this.app = app;
42	  }
43	
44	  functional = () => !!this.dc;
45	
46	  /**
47	   * Search across all discourse nodes (files that have frontmatter nodeTypeId)
48	   */
49	  searchDiscourseNodesByTitle = (
50	    query: string,
51	    nodeTypeId?: string,
52	  ): TFile[] => {
53	    if (!query || query.length < this.MIN_QUERY_LENGTH) {
54	      return [];
55	    }
56	    const datacore = this.getReadyDatacore();
57	    if (!datacore) {
58	      return this.fallbackSearchDiscourseNodesByTitle(query, nodeTypeId);
59	    }
60	
61	    try {
62	      const dcQuery = nodeTypeId
63	        ? `@page and exists(nodeTypeId) and nodeTypeId = "${nodeTypeId}"`
64	        : "@page and exists(nodeTypeId)";
65	      const potentialNodes = datacore.query(dcQuery);
66	
67	      const searchResults = potentialNodes.filter((p: DatacorePage) =>
68	        this.fuzzySearch(p.$name, query),
69	      );
70	
71	      const files = searchResults
72	        .map((dcFile: DatacorePage) => {
73	          if (dcFile && dcFile.$path) {
74	            const realFile = this.app.vault.getAbstractFileByPath(dcFile.$path);
75	            if (realFile && realFile instanceof TFile) return realFile;
76	          }
77	          return null;
78	        })
79	        .filter((f): f is TFile => f instanceof TFile);
80	
81	      return files.reverse();
82	    } catch (error) {
83	      console.error("Error in searchDiscourseNodesByTitle:", error);
84	      return this.fallbackSearchDiscourseNodesByTitle(query, nodeTypeId);
85	    }
86	  };
87	
88	  /**
89	   * Search across all discourse nodes that have nodeInstanceId
90	   */
91	  getDiscourseNodeById = (nodeInstanceId: string): TFile | null => {
92	    if (!nodeInstanceId.match(/^[-.+\w]+$/)) {
93	      console.error("Malformed id:", nodeInstanceId);
94	      return null;
95	    }
96	
97	    const datacore = this.getReadyDatacore();
98	    if (!datacore) {
99	      return this.fallbackGetDiscourseNodeById(nodeInstanceId);
100	    }
101	
102	    try {
103	      const dcQuery = `@page and exists(nodeInstanceId) and nodeInstanceId = "${nodeInstanceId}"`;
104	      const potentialNodes = datacore.query(dcQuery);
105	      const path = potentialNodes.at(0)?.$path;
106	      if (!path) return null;
107	      return this.app.vault.getFileByPath(path);
108	    } catch (error) {
109	      console.error("Error in searchDiscourseNodeById:", error);
110	      return this.fallbackGetDiscourseNodeById(nodeInstanceId);
111	    }
112	  };
113	
114	  searchCompatibleNodeByTitle = ({
115	    query,
116	    compatibleNodeTypeIds,
117	    activeFile,
118	    selectedRelationType,
119	  }: {
120	    query: string;
121	    compatibleNodeTypeIds: string[];
122	    activeFile: TFile;
123	    selectedRelationType: string;
124	  }): TFile[] => {
125	    if (!query || query.length < this.MIN_QUERY_LENGTH) {
126	      return [];
127	    }
128	    const datacore = this.getReadyDatacore();
129	    if (!datacore) {
130	      return this.fallbackSearchCompatibleNodeByTitle({
131	        query,
132	        compatibleNodeTypeIds,
133	        activeFile,
134	        selectedRelationType,
135	      });
136	    }
137	
138	    try {
139	      const dcQuery = `@page and exists(nodeTypeId) and ${compatibleNodeTypeIds
140	        .map((id) => `nodeTypeId = "${id}"`)
141	        .join(" or ")}`;
142	
143	      const potentialNodes = datacore.query(dcQuery);
144	      const searchResults = potentialNodes.filter((p: DatacorePage) => {
145	        return this.fuzzySearch(p.$name, query);
146	      });
147	
148	      let existingRelatedFiles: string[] = [];
149	      if (selectedRelationType) {
150	        const fileCache = this.app.metadataCache.getFileCache(activeFile);
151	        const existingRelations: string[] =
152	          (fileCache?.frontmatter?.[selectedRelationType] as string[]) || [];
153	
154	        existingRelatedFiles = existingRelations.map((relation: string) => {
155	          const match = relation.match(/\[\[(.*?)(?:\|.*?)?\]\]/);
156	          return match?.[1] ?? relation.replace(/^\[\[|\]\]$/g, "");
157	        });
158	      }
159	      const finalResults = searchResults
160	        .map((dcFile: DatacorePage) => {
161	          if (dcFile && dcFile.$path) {
162	            const realFile = this.app.vault.getAbstractFileByPath(dcFile.$path);
163	            if (realFile && realFile instanceof TFile) {
164	              return realFile;
165	            }
166	          }
167	          return null;
168	        })
169	        .filter((f): f is TFile => f instanceof TFile)
170	        .filter((file: TFile) => {
171	          if (file.path === activeFile.path) return false;
172	
173	          if (
174	            selectedRelationType &&
175	            existingRelatedFiles.some((existingFile) => {
176	              return (
177	                file.basename === existingFile.replace(/\.md$/, "") ||
178	                file.name === existingFile
179	              );
180	            })
181	          ) {
182	            return false;
183	          }
184	
185	          return true;
186	        });
187	
188	      return finalResults;
189	    } catch (error) {
190	      console.error("Error in searchNodeByTitle:", error);
191	      return this.fallbackSearchCompatibleNodeByTitle({
192	        query,
193	        compatibleNodeTypeIds,
194	        activeFile,
195	        selectedRelationType,
196	      });
197	    }
198	  };
