326	  /**
327	   * Return all markdown pages under import/ that have importedFromRid and nodeInstanceId.
328	   * Uses DataCore when available; falls back to vault iteration otherwise.
329	   */
330	  getImportedNodePages = (): TFile[] => {
331	    const datacore = this.getReadyDatacore();
332	    if (datacore) {
333	      try {
334	        const dcQuery = `@page and path("import") and exists(importedFromRid) and exists(nodeInstanceId)`;
335	        const pages = datacore.query(dcQuery);
336	        const files: TFile[] = [];
337	        for (const page of pages) {
338	          if (page.$path) {
339	            const file = this.app.vault.getAbstractFileByPath(page.$path);
340	            if (file && file instanceof TFile) files.push(file);
341	          }
342	        }
343	        return files;
344	      } catch (error) {
345	        console.warn("DataCore query for imported nodes failed:", error);
346	      }
347	    }
348	    return this.fallbackGetImportedNodePages();
349	  };
