351	  /**
352	   * Return all markdown files that have nodeInstanceId in frontmatter.
353	   * Uses DataCore when available; falls back to vault iteration otherwise.
354	   */
355	  getFilesWithNodeInstanceId = (): TFile[] => {
356	    const datacore = this.getReadyDatacore();
357	    if (datacore) {
358	      try {
359	        const dcQuery = `@page and exists(nodeInstanceId)`;
360	        const pages = datacore.query(dcQuery);
361	        const files: TFile[] = [];
362	        for (const page of pages) {
363	          if (page.$path) {
364	            const file = this.app.vault.getAbstractFileByPath(page.$path);
365	            if (file && file instanceof TFile) files.push(file);
366	          }
367	        }
368	        return files;
369	      } catch (error) {
370	        console.warn(
371	          "DataCore query for files with nodeInstanceId failed:",
372	          error,
373	        );
374	      }
375	    }
376	    return this.fallbackGetFilesWithNodeInstanceId();
