378	
379	  /**
380	   * Return all markdown files that have nodeTypeId in frontmatter.
381	   * When excludeImported is true, only returns files without importedFromRid.
382	   * Uses DataCore when available; falls back to vault iteration otherwise.
383	   */
384	  getFilesWithNodeTypeId = (opts?: { excludeImported?: boolean }): TFile[] => {
385	    const datacore = this.getReadyDatacore();
386	    if (datacore) {
387	      try {
388	        const dcQuery = `@page and exists(nodeTypeId)`;
389	        const pages = datacore.query(dcQuery);
390	        const files: TFile[] = [];
391	        for (const page of pages) {
392	          if (!page.$path) continue;
393	          const file = this.app.vault.getAbstractFileByPath(page.$path);
394	          if (!(file && file instanceof TFile)) continue;
395	          if (opts?.excludeImported) {
396	            const fm = this.app.metadataCache.getFileCache(file)
397	              ?.frontmatter as Record<string, unknown> | undefined;
398	            if (fm?.importedFromRid) continue;
399	          }
400	          files.push(file);
401	        }
402	        return files;
403	      } catch (error) {
404	        console.warn("DataCore query for files with nodeTypeId failed:", error);
405	      }
406	    }
407	    return this.fallbackGetFilesWithNodeTypeId(opts);
408	  };
