410	  /**
411	   * Find a file by importedFromRid in frontmatter.
412	   * Uses DataCore when available; falls back to vault iteration otherwise.
413	   */
414	  getFileByImportedFromRid = (importedFromRid: string): TFile | null => {
415	    const datacore = this.getReadyDatacore();
416	    if (datacore) {
417	      try {
418	        const safeUri = importedFromRid
419	          .replace(/\\/g, "\\\\")
420	          .replace(/"/g, '\\"');
421	        const dcQuery = `@page and importedFromRid = "${safeUri}"`;
422	        const results = datacore.query(dcQuery);
423	        const path = results.at(0)?.$path;
424	        if (path) {
425	          const file = this.app.vault.getAbstractFileByPath(path);
426	          if (file && file instanceof TFile) return file;
427	        }
428	      } catch (error) {
429	        console.warn(
430	          "DataCore query for file by importedFromRid failed:",
431	          error,
432	        );
433	      }
434	    }
435	    const allFiles = this.app.vault.getMarkdownFiles();
436	    for (const f of allFiles) {
437	      const fm = this.app.metadataCache.getFileCache(f)?.frontmatter;
438	      if (
439	        (fm as Record<string, unknown> | undefined)?.importedFromRid ===
440	        importedFromRid
441	      ) {
442	        return f;
443	      }
444	    }
445	    return null;
446	  };
