448	  /**
449	   * Find a file by nodeInstanceId or importedFromRid (endpoint id).
450	   * Tries DataCore getDiscourseNodeById and getFileByImportedFromRid when available;
451	   * falls back to iterating files with nodeInstanceId and matching either field.
452	   */
453	  getFileByEndpoint = (endpointId: string): TFile | null => {
454	    if (this.getReadyDatacore()) {
455	      const byId = this.getDiscourseNodeById(endpointId);
