457	      const byRid = this.getFileByImportedFromRid(endpointId);
458	      if (byRid) return byRid;
459	    }
460	    const files = this.getFilesWithNodeInstanceId();
461	    for (const file of files) {
462	      const fm = this.app.metadataCache.getFileCache(file)?.frontmatter as
463	        | Record<string, unknown>
464	        | undefined;
465	      const id = fm?.nodeInstanceId as string | undefined;
466	      const rid = fm?.importedFromRid as string | undefined;
467	      if (id === endpointId || rid === endpointId) return file;
468	    }
469	    return null;
470	  };
