472	  /**
473	   * Find an existing imported file by nodeInstanceId and importedFromRid
474	   * Uses DataCore when available; falls back to vault iteration otherwise
475	   * Returns the file if found, null otherwise
476	   */
477	  findExistingImportedFile = (
478	    nodeInstanceId: string,
479	    importedFromRid: string,
480	  ): TFile | null => {
481	    const datacore = this.getReadyDatacore();
482	    if (datacore) {
483	      try {
484	        const safeId = nodeInstanceId
485	          .replace(/\\/g, "\\\\")
486	          .replace(/"/g, '\\"');
487	        const safeUri = importedFromRid
488	          .replace(/\\/g, "\\\\")
489	          .replace(/"/g, '\\"');
490	        const dcQuery = `@page and nodeInstanceId = "${safeId}" and importedFromRid = "${safeUri}"`;
491	        const results = datacore.query(dcQuery);
492	
493	        for (const page of results) {
494	          if (page.$path) {
495	            const file = this.app.vault.getAbstractFileByPath(page.$path);
496	            if (file && file instanceof TFile) {
497	              return file;
498	            }
499	          }
500	        }
501	      } catch (error) {
502	        // DataCore query may fail; vault-iteration fallback below handles this
503	      }
504	    }
505	
506	    // Fallback: DataCore absent, query failed, or indexed field mismatch
507	    const allFiles = this.app.vault.getMarkdownFiles();
508	    for (const f of allFiles) {
509	      const fm = this.app.metadataCache.getFileCache(f)?.frontmatter;
510	      if (
511	        fm?.nodeInstanceId === nodeInstanceId &&
512	        fm.importedFromRid === importedFromRid
513	      ) {
514	        return f;
515	      }
516	    }
517	    return null;
518	  };
