524	  private fallbackSearchDiscourseNodesByTitle(
525	    query: string,
526	    nodeTypeId?: string,
527	  ): TFile[] {
528	    return this.app.vault
529	      .getMarkdownFiles()
530	      .filter((file) => {
531	        const fm = this.app.metadataCache.getFileCache(file)?.frontmatter as
532	          | Record<string, unknown>
533	          | undefined;
534	        if (!fm?.nodeTypeId) return false;
535	        if (nodeTypeId && fm.nodeTypeId !== nodeTypeId) return false;
536	        return this.fuzzySearch(file.basename, query);
537	      })
538	      .reverse();
539	  }
