541	  private fallbackGetDiscourseNodeById(nodeInstanceId: string): TFile | null {
542	    for (const file of this.app.vault.getMarkdownFiles()) {
543	      const fm = this.app.metadataCache.getFileCache(file)?.frontmatter as
544	        | Record<string, unknown>
545	        | undefined;
546	      if (fm?.nodeInstanceId === nodeInstanceId) return file;
547	    }
548	    return null;
549	  }
