597	  private fallbackGetImportedNodePages(): TFile[] {
598	    const files: TFile[] = [];
599	    const allFiles = this.app.vault.getMarkdownFiles();
600	    for (const f of allFiles) {
601	      if (!f.path.startsWith("import/")) continue;
602	      const fm = this.app.metadataCache.getFileCache(f)?.frontmatter;
603	      if (
604	        (fm as Record<string, unknown> | undefined)?.importedFromRid &&
605	        (fm as Record<string, unknown> | undefined)?.nodeInstanceId
606	      ) {
607	        files.push(f);
608	      }
609	    }
610	    return files;
611	  }
