613	  private fallbackGetFilesWithNodeInstanceId(): TFile[] {
614	    const files: TFile[] = [];
615	    const allFiles = this.app.vault.getMarkdownFiles();
616	    for (const f of allFiles) {
617	      const fm = this.app.metadataCache.getFileCache(f)?.frontmatter;
618	      if ((fm as Record<string, unknown> | undefined)?.nodeInstanceId) {
619	        files.push(f);
620	      }
621	    }
622	    return files;
623	  }
624	
625	  private fallbackGetFilesWithNodeTypeId(opts?: {
626	    excludeImported?: boolean;
627	  }): TFile[] {
628	    const files: TFile[] = [];
629	    const allFiles = this.app.vault.getMarkdownFiles();
630	    for (const f of allFiles) {
631	      const fm = this.app.metadataCache.getFileCache(f)?.frontmatter as
632	        | Record<string, unknown>
633	        | undefined;
634	      const nodeTypeId = fm?.nodeTypeId;
635	      if (!nodeTypeId) continue;
636	      if (
637	        opts?.excludeImported &&
638	        (fm?.importedFromRid || fm?.importedFromSpaceUri)
639	      ) {
640	        continue;
641	      }
642	      files.push(f);
643	    }
644	    return files;
645	  }
646	
647	  private fallbackScanVault(
648	    patterns: BulkImportPattern[],
649	    validNodeTypes: DiscourseNode[],
650	  ): BulkImportCandidate[] {
651	    const candidates: BulkImportCandidate[] = [];
652	    const allFiles = this.app.vault.getMarkdownFiles();
653	
654	    for (const file of allFiles) {
655	      const fileName = file.basename;
656	      const fileCache = this.app.metadataCache.getFileCache(file);
657	      const currentNodeTypeId = fileCache?.frontmatter?.nodeTypeId as
658	        | string
659	        | undefined;
660	
661	      if (
662	        currentNodeTypeId &&
663	        validNodeTypes.some((nt) => nt.id === currentNodeTypeId)
664	      ) {
665	        continue;
666	      }
667	
668	      for (const pattern of patterns) {
669	        if (!pattern.enabled || !pattern.alternativePattern.trim()) continue;
670	
671	        const regex = getDiscourseNodeFormatExpression(
672	          pattern.alternativePattern,
673	        );
674	
675	        if (regex.test(fileName)) {
676	          const extractedContent = extractContentFromTitle(
677	            pattern.alternativePattern,
678	            fileName,
679	          );
680	
681	          const matchedNodeType = validNodeTypes.find(
682	            (nt) => nt.id === pattern.nodeTypeId,
683	          );
684	
685	          if (!matchedNodeType) {
686	            continue;
687	          }
688	
689	          candidates.push({
690	            file,
691	            matchedNodeType,
692	            alternativePattern: pattern.alternativePattern,
693	            extractedContent,
694	            selected: false,
695	          });
696	          break;
697	        }
698	      }
699	    }
700	
701	    return candidates;
702	  }
703	}
704	
705	/**
706	 * Returns raw imported node entries from import/ folder (no DB).
707	 * Uses DataCore when available; otherwise iterates vault. Only includes files
708	 * that have both importedFromRid and nodeInstanceId in frontmatter.
709	 */
710	export const getImportedNodesRaw = ({
711	  queryEngine,
712	  plugin,
713	}: {
714	  queryEngine?: QueryEngine;
715	  plugin: DiscourseGraphPlugin;
716	}): { importedFromRid: string; nodeInstanceId: string }[] => {
717	  const engine = queryEngine ?? new QueryEngine(plugin.app);
718	  const files = engine.getImportedNodePages();
719	
720	  const entries: { importedFromRid: string; nodeInstanceId: string }[] = [];
721	  for (const file of files) {
722	    const cache = plugin.app.metadataCache.getFileCache(file);
723	    const frontmatter = cache?.frontmatter;
724	    const importedFromRid = frontmatter?.importedFromRid as string | undefined;
725	    const nodeInstanceId = frontmatter?.nodeInstanceId as string | undefined;
726	    if (importedFromRid && nodeInstanceId) {
727	      entries.push({ importedFromRid, nodeInstanceId });
728	    }
729	  }
