  /** Hides the search-existing-nodes dropdown. Used when intent is always to create
   *  (e.g. file explorer "Convert into"), not to reuse an existing node. */
  disableExistingNodeSearch?: boolean;
  plugin: DiscourseGraphPlugin;
};

export const ModifyNodeForm = ({
  nodeTypes,
  onSubmit,
  onCancel,
  initialTitle = "",
  initialNodeType,
  initialFile,
  currentFile,
  disableExistingNodeSearch = false,
  plugin,
}: ModifyNodeFormProps) => {
  const isEditMode = !!initialFile;
  const [title, setTitle] = useState(initialFile?.basename || initialTitle);
  const [selectedNodeType, setSelectedNodeType] =
    useState<DiscourseNode | null>(initialNodeType || null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedExistingNode, setSelectedExistingNode] =
    useState<TFile | null>(null);
  const [query, setQuery] = useState(initialFile?.basename || initialTitle);
  const [activeIndex, setActiveIndex] = useState(0);
  const [isFocused, setIsFocused] = useState(false);
  const [searchResults, setSearchResults] = useState<TFile[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [selectedRelationshipKey, setSelectedRelationshipKey] = useState<
    string | undefined
  >(undefined);
  const queryEngine = useRef(new QueryEngine(plugin.app));
  const titleInputRef = useRef<HTMLTextAreaElement>(null);
  const popoverRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLUListElement>(null);
  const debounceTimeoutRef = useRef<number | null>(null);
  const selectedFileRef = useRef<TFile | null>(null);

  const maxTitleBytes = useMemo(
    () => computeMaxTitleBytes(selectedNodeType),
    [selectedNodeType],
  );

  // Search for nodes when query changes (only in create mode, and only when search is enabled)
  useEffect(() => {
    if (isEditMode || disableExistingNodeSearch) {
      setSearchResults([]);
      return;
    }
    const searchQuery = query.trim();
    if (searchQuery.length < 2) {
      setSearchResults([]);
      return;
    }

    if (debounceTimeoutRef.current) {
      window.clearTimeout(debounceTimeoutRef.current);
    }

    setIsSearching(true);
    debounceTimeoutRef.current = window.setTimeout(() => {
      void (() => {
        try {
          const results = selectedNodeType
            ? queryEngine.current.searchDiscourseNodesByTitle(
                searchQuery,
                selectedNodeType.id,
              )
            : queryEngine.current.searchDiscourseNodesByTitle(searchQuery);
          setSearchResults(results);
        } catch (error) {
          console.error("Error searching nodes:", error);
          setSearchResults([]);
        } finally {
          setIsSearching(false);
        }
      })();
    }, 250);
    return () => {
      if (debounceTimeoutRef.current) {
        window.clearTimeout(debounceTimeoutRef.current);
      }
    };
  }, [query, selectedNodeType, isEditMode, disableExistingNodeSearch]);

  const isOpen = useMemo(() => {
    return (
      !disableExistingNodeSearch &&
      !selectedExistingNode &&
      isFocused &&
      searchResults.length > 0 &&
      query.trim().length >= 2
    );
  }, [
    disableExistingNodeSearch,
    selectedExistingNode,
    isFocused,
    searchResults.length,
    query,
  ]);

