    const sample = byType[t.id]?.[0];
    const q = sample ? sample.split(/\s+/).filter((w) => w.length > 3).slice(-1)[0] : null;
    const dcCount = dc.query(`@page and exists(nodeTypeId) and nodeTypeId = "${t.id}"`).length;
    return { name: t.name, metadataCacheCount: byType[t.id]?.length ?? 0, datacoreCount: dcCount, sample, q };
  });
})()
