SP=/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/35678f0a-54e5-4aa4-8303-f9f3d339c60c/scratchpad/cdp
cat > $SP/menu.js <<'EOF'
(() => {
  const { Menu, MarkdownView } = require("obsidian");
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  let view = app.workspace.getActiveViewOfType(MarkdownView);
  if (!view) { let found; app.workspace.iterateRootLeaves((l) => { if (!found && l.view instanceof MarkdownView) found = l.view; }); view = found; }
  if (!view) return { error: "no markdown view open" };
  app.workspace.setActiveLeaf(view.leaf, { focus: true });
  const ed = view.editor, before = ed.getValue();
  // Find a 'node' word in the note to select; otherwise report.
  const idx = before.toLowerCase().indexOf("node");
  if (idx < 0) return { error: "active note has no 'node' text to select", file: view.file?.path };
  const from = ed.offsetToPos(idx), to = ed.offsetToPos(idx + 4);
  ed.setSelection(from, to);
  document.querySelectorAll(".modal-container").forEach((el) => el.remove());
  const menu = new Menu();
  app.workspace.trigger("editor-menu", menu, ed, view);
  const item = menu.items.find((i) => (i.titleEl?.textContent || "").includes("Turn into discourse node"));
  if (!item) return { error: "menu item missing", titles: menu.items.map((i) => i.titleEl?.textContent) };
  const sub = item.submenu;
  const first = sub.items[0];
  const firstName = first.titleEl?.textContent;
  first.callback?.(new MouseEvent("click"));
  return sleep(700).then(() => {
    const m = document.querySelector(".modal-container .modal");
    const ta = m?.querySelector("textarea");
    const r = { file: view.file?.path, firstSubmenuItem: firstName, modalOpen: !!m, textarea: ta?.value, activeIsTextarea: document.activeElement === ta,
      select: m?.querySelector("select")?.selectedOptions[0]?.textContent, dropdownItems: m?.querySelectorAll("li").length, noteUnchanged: ed.getValue() === before };
    document.querySelectorAll(".modal-container").forEach((el) => el.remove());
    return r;
  });
})()
EOF
cd $SP && node cdp.mjs menu.js

